+const cases = [[0, 19], [1, -7], [2, 2147483647], [7, -2147483648], [31, 2147483630], [1000, -19]];
+function updated(values, count) {
+  const result = [...values];
+  for (let step = 0; step < count; step++) result[result.length - 1] = (result[result.length - 1] + 1) | 0;
+  return result;
+}
