        return `func project${index}(value gopurs_runtime.Value) []int64 { native := ${expr}; return []int64{${fields.join(',')}} }`;
    }).join('\n');
    const directory = goModule(t, 'gopurs-record-projection-guard-', { runtime: runtimeGoCode });
    writeGoFile(directory, 'projection_test.go', `package main
import("fmt";"reflect";"testing";"unsafe";"gopurs/output/gopurs_runtime")
var reads int
var trace []string
func once(value gopurs_runtime.Value) gopurs_runtime.Value {reads++;return value}
${functions}
type outcome struct { values []int64; failure string; log []string }
func observe(run func()[]int64)(out outcome){trace=nil;defer func(){if p:=recover();p!=nil{out.failure=fmt.Sprint(p)};out.log=append([]string{},trace...)}();out.values=run();return}
func compact(keys []string, values []gopurs_runtime.Value)gopurs_runtime.Value{switch len(keys){
case 1:return gopurs_runtime.RecordDict1(keys[0],values[0])
case 2:return gopurs_runtime.RecordDict2(keys[0],keys[1],values[0],values[1])
case 3:return gopurs_runtime.RecordDict3(keys[0],keys[1],keys[2],values[0],values[1],values[2])
case 5:return gopurs_runtime.RecordDict5(keys[0],keys[1],keys[2],keys[3],keys[4],values[0],values[1],values[2],values[3],values[4])
};return gopurs_runtime.RecordDict(keys,values)}
func TestProjectionMatrix(t *testing.T){cases:=[]struct{keys []string;project func(gopurs_runtime.Value)[]int64}{
${shapes.map((keys, i) => `{[]string{${keys.map(quote).join(',')}},project${i}}`).join(',\n')},
};checks:=0
for _,c:=range cases{values:=make([]gopurs_runtime.Value,len(c.keys));boxed:=map[string]gopurs_runtime.Value{};foreign:=map[string]any{};for i,k:=range c.keys{values[i]=gopurs_runtime.Int(int64(2147483647-i*99));boxed[k]=values[i];foreign[k]=int64(values[i].IntVal)}
reverseKeys:=append([]string{},c.keys...);reverseValues:=append([]gopurs_runtime.Value{},values...);for i,j:=0,len(c.keys)-1;i<j;i,j=i+1,j-1{reverseKeys[i],reverseKeys[j]=reverseKeys[j],reverseKeys[i];reverseValues[i],reverseValues[j]=reverseValues[j],reverseValues[i]}
duplicateKeys:=append([]string{c.keys[len(c.keys)-1]},c.keys...);duplicateValues:=append([]gopurs_runtime.Value{gopurs_runtime.Int(-987)},values...)
sameKeys:=append([]string{},c.keys...);sameKeys[len(sameKeys)-1]=sameKeys[0]
inputs:=[]gopurs_runtime.Value{
gopurs_runtime.RecordDict(c.keys,values),compact(c.keys,values),gopurs_runtime.RecordDict(reverseKeys,reverseValues),
gopurs_runtime.RecordDict(append(append([]string{},c.keys...),"extra"),append(append([]gopurs_runtime.Value{},values...),gopurs_runtime.Int(1))),
gopurs_runtime.RecordDict(duplicateKeys,duplicateValues),gopurs_runtime.RecordDict(sameKeys,values),compact(sameKeys,values),
gopurs_runtime.RecordDict(c.keys[:len(c.keys)-1],values[:len(values)-1]),gopurs_runtime.RecordDict(c.keys,values[:len(values)-1]),
gopurs_runtime.Record(boxed),gopurs_runtime.Any(foreign),gopurs_runtime.Record(map[string]gopurs_runtime.Value{}),
{Type:gopurs_runtime.TypeConstructor,IntVal:777},{},
}
gopurs_runtime.StructGetters[777]=func(_ unsafe.Pointer,k string)gopurs_runtime.Value{trace=append(trace,k);return boxed[k]}
for mode,input:=range inputs{expected:=observe(func()[]int64{result:=make([]int64,len(c.keys));for i,k:=range c.keys{result[i]=gopurs_runtime.RecordGet(input,k).IntVal};return result});reads=0;actual:=observe(func()[]int64{return c.project(input)});if !reflect.DeepEqual(actual,expected)||reads!=1{t.Fatalf("size=%d mode=%d actual=%+v expected=%+v reads=%d",len(c.keys),mode,actual,expected,reads)};checks++}
// A previous successful shape check is not cached across later key changes.
mutableKeys:=append([]string{},c.keys...);mutableValues:=append([]gopurs_runtime.Value{},values...);input:=gopurs_runtime.RecordDict(mutableKeys,mutableValues);first:=c.project(input);if len(c.keys)>1{last:=len(c.keys)-1;mutableKeys[0],mutableKeys[last]=mutableKeys[last],mutableKeys[0];mutableValues[0],mutableValues[last]=mutableValues[last],mutableValues[0]};if !reflect.DeepEqual(first,c.project(input)){t.Fatal("shape result was cached")};first[0]=0;if gopurs_runtime.RecordGet(input,c.keys[0]).IntVal!=values[0].IntVal{t.Fatal("projection mutated source")}
};t.Logf("%d representation/shape checks passed",checks)}
`);
    runGo(directory, ['test', '-count=1', '.']);
});

