#!/usr/bin/env python3
"""Replay unchanged record-update actions with runtime counts, fields and representations, without timing."""
import argparse
import difflib
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def callback_adapter(sources):
    matches = []
    for path, text in sources.items():
        if 'func Bench_MeasureBatch_runEffectWorker(' not in text:
            continue
        worker = text.split('func Bench_MeasureBatch_runEffectWorker(', 1)[1]
        match = re.search(r'\bgo_arg2\s*:=\s*(.*?)\n\s*go_action\s*:=\s*Bench_MeasureBatch\(go_arg0,\s*go_arg1,\s*go_arg2\)', worker, re.S)
        assert match, 'Cannot identify generated measurement callback conversion'
        aliases = re.findall(r'\b([A-Za-z_][A-Za-z0-9_]*)\s+"gopurs/output/gopurs_runtime"', text)
        assert len(aliases) == 1
        expression = re.sub(r'\b' + re.escape(aliases[0]) + r'\.', 'r.', match[1].strip())
        matches.append({'source': 'func convertCallback(arg2 r.Value) func() int {\n go_arg2 := ' + expression + '\n return go_arg2\n}\n',
                        'generated_source': str(path), 'generated_sha256': digest(path)})
    assert len(matches) == 1
    return matches[0]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('build', type=Path)
    parser.add_argument('proof', type=Path)
    parser.add_argument('--prepare-only', action='store_true')
    args = parser.parse_args()
    output = (args.build / 'output').resolve()
    proof = args.proof.resolve()
    proof.mkdir(parents=True, exist_ok=False)
    widths = {'RecordSetSmall1000': 2, 'RecordSetMedium1000': 8, 'RecordSetLarge1000': 16}
    names = list(widths)
    counts = [0, 1, 2, 7, 1000, 65535]
    inputs = []
    for name, width in widths.items():
        fields = [list(range(1, width + 1)), [0] * width,
                  [2147483647 if i % 2 == 0 else -2147483648 for i in range(width)],
                  [-(i + 1) * 17 for i in range(width)],
                  [i - 9 for i in range(width - 1)] + [2147483647]]
        variants = [{'count': count, 'fields': values, 'layout': layout}
                    for count in counts for values in fields for layout in ['shape', 'dictionary', 'reversed', 'map']]
        variants += [{'count': count, 'fields': fields[0], 'layout': 'prepared'} for count in counts]
        inputs.extend({'case': index, 'name': name, **variant} for index, variant in enumerate(variants))
    (proof / 'inputs.json').write_text(json.dumps(inputs, indent=2) + '\n')
    sources = {p: p.read_text() for p in (output / 'purescript').rglob('*.go')}
    source_hashes = {str(p): digest(p) for p in sources}
    opaque = [(p, text) for p, text in sources.items() if 'func opaqueValue(a interface{}) interface{}' in text]
    assert len(opaque) == 1
    original, text = opaque[0]
    rewritten, replacements = re.subn(r'func opaqueValue\(a interface\{\}\) interface\{\} \{\s*return a\s*\}', '''func opaqueValue(a interface{}) interface{} {
        if RecordAuditPreparing { RecordAuditPrepared = a }
        if RecordAuditCalls >= len(RecordAuditInputs) { panic("unexpected opaque call") }
        value := RecordAuditInputs[RecordAuditCalls]
        RecordAuditCalls++
        if value == nil { return a }
        return value
    }''', text)
    assert replacements == 1
    rewritten += '\nvar RecordAuditInputs []interface{}\nvar RecordAuditCalls int\nvar RecordAuditPreparing bool\nvar RecordAuditPrepared interface{}\n'
    override = proof / 'opaque-override.go'
    override.write_text(rewritten)
    (proof / 'opaque-override.patch').write_text(''.join(difflib.unified_diff(text.splitlines(True), rewritten.splitlines(True),
                                                                                       fromfile=str(original), tofile=str(override))))
    (proof / 'overlay.json').write_text(json.dumps({'Replace': {str(original): str(override)}}, indent=2) + '\n')
    owners = {}
    for name in names:
        matches = [p.parent.relative_to(output).as_posix() for p, text in sources.items()
                   if f'func Get_Test_{name}_prepare(' in text]
        assert len(matches) == 1, (name, matches)
        owners[name] = matches[0]
    boundary = original.parent.relative_to(output).as_posix()
    packages = sorted(set(owners.values()) | {boundary})
    aliases = {package: 'p' + str(i) for i, package in enumerate(packages)}
    imports = '\n'.join(f'{alias} "gopurs/output/{package}"' for package, alias in aliases.items())
    actions = ','.join(f'"{name}":{aliases[owners[name]]}.Get_Test_{name}_prepare' for name in names)
    adapter = callback_adapter(sources)
    program = '''package main
import("encoding/json";"fmt";"os";r "gopurs/output/gopurs_runtime"
IMPORTS
)
type Input struct{Case int `json:"case"`;Name string `json:"name"`;Count int64 `json:"count"`;Fields []int64 `json:"fields"`;Layout string `json:"layout"`}
func record(input Input,prepared r.Value)r.Value{
 if input.Layout=="prepared"{return prepared}
 keys:=make([]string,len(input.Fields));values:=make([]r.Value,len(input.Fields));fields:=map[string]r.Value{}
 for i,value:=range input.Fields{keys[i]=string(rune('a'+i));values[i]=r.Int(value);fields[keys[i]]=values[i]}
 if input.Layout=="map"{return r.Record(fields)}
 if input.Layout=="shape"&&len(keys)==2{return r.RecordShape2(&r.RecordKeys2{K0:keys[0],K1:keys[1]},values[0],values[1])}
 if input.Layout=="reversed"{for i,j:=0,len(keys)-1;i<j;i,j=i+1,j-1{keys[i],keys[j]=keys[j],keys[i];values[i],values[j]=values[j],values[i]}}
 return r.RecordDict(keys,values)
}
func unchanged(value r.Value,input Input){
 for i,expected:=range input.Fields{actual:=r.RecordGet(value,string(rune('a'+i)));if actual.Type!=r.TypeInt||actual.IntVal!=expected{panic("original record field mutated")}}
 if len(r.RecordToMap(value))!=len(input.Fields){panic("record keys changed")}
}
func main(){
 var inputs []Input;f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};if e=json.NewDecoder(f).Decode(&inputs);e!=nil{panic(e)}
 factories:=map[string]func()r.Value{ACTIONS};actions:=map[string]r.Value{};prepared:=map[string]r.Value{}
 for name,factory:=range factories{
   BOUNDARY.RecordAuditInputs=[]interface{}{nil};BOUNDARY.RecordAuditCalls=0;BOUNDARY.RecordAuditPreparing=true
   action:=r.Apply(factory(),r.Value{})
   if BOUNDARY.RecordAuditCalls!=1{panic("incorrect opaque calls during preparation")}
   BOUNDARY.RecordAuditPreparing=false
   prepared[name]=r.AnyToValue(BOUNDARY.RecordAuditPrepared);actions[name]=action
 }
 for _,input:=range inputs{
   action:=actions[input.Name];original:=record(input,prepared[input.Name]);unchanged(original,input)
   for _,path:=range []string{"Apply","ffi_conversion","forced_fallback"}{
     BOUNDARY.RecordAuditInputs=[]interface{}{original,r.Int(input.Count)};BOUNDARY.RecordAuditCalls=0
     var result int64
     if path=="Apply"{value:=r.Apply(action,r.Value{});if value.Type!=r.TypeInt{panic("not an Int")};result=value.IntVal}else{
       selected:=action
       if path=="forced_fallback"{selected=r.Func(func(_ r.Value)r.Value{return r.Apply(action,r.Value{})})}
       result=int64(convertCallback(selected)())
     }
     if BOUNDARY.RecordAuditCalls!=2{panic("incorrect opaque calls per action")}
     unchanged(original,input)
     fmt.Printf("%s %d %s %d\\n",input.Name,input.Case,path,result)
   }
 }
}
'''.replace('IMPORTS', imports).replace('ACTIONS', actions).replace('BOUNDARY', aliases[boundary]) + adapter['source']
    (proof / 'main.go').write_text(program)
    oracle = '''import fs from 'node:fs';
const inputs=JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
for(const {name,case:identifier,fields,count} of inputs){
  let original=0;for(const field of fields)original=(original+field)|0;
  let last=fields[fields.length-1];for(let step=0;step<count;step++)last=(last+1)|0;
  let final=0;for(let index=0;index<fields.length;index++)final=(final+(index===fields.length-1?last:fields[index]))|0;
  const result=(original+final)|0;
  for(const path of ['Apply','ffi_conversion','forced_fallback'])console.log(`${name} ${identifier} ${path} ${result}`);
}
'''
    (proof / 'oracle.mjs').write_text(oracle)
    command = ['go', 'run', '-overlay=' + str(proof / 'overlay.json'), str(proof / 'main.go'), str(proof / 'inputs.json')]
    manifest = {'build': str(args.build.resolve()), 'binary_sha256': digest(args.build / 'benchmark'),
                'generated_source_sha256': source_hashes, 'override_sha256': digest(override), 'command': command,
                'input_variants': len(inputs), 'preparation_opaque_calls_per_case': {name: 1 for name in names},
                'action_opaque_calls_per_case': {name: 2 for name in names},
                'paths': ['Apply', 'ffi_conversion', 'forced_fallback'], 'oracles': len(inputs) * 3,
                'preparation_input': 'original unchanged fixture', 'record_representations': ['prepared', 'shape', 'dictionary', 'reversed', 'map'], 'counter_domain': counts, 'action_replayed_with_changing_inputs': True, 'inputs_immutable': True,
                'callback_adapter': adapter,
                'limitation': 'Only the diagnostic overlay replaces opaque; production sources and binaries remain unchanged. Negative counts are excluded: the original Int32 countdown reaches zero only after billions of iterations. Int32 boundary values are exercised in all record fields, with bounded nonnegative counts. The prepared layout reuses the exact original prepare result.'}
    if not args.prepare_only:
        result = subprocess.run(command, cwd=output, env={**os.environ, 'GOWORK': 'off'}, text=True,
                                capture_output=True, timeout=120)
        (proof / 'stdout.txt').write_text(result.stdout)
        (proof / 'stderr.txt').write_text(result.stderr)
        assert result.returncode == 0, result.stderr
        expected = subprocess.check_output(['node', str(proof / 'oracle.mjs'), str(proof / 'inputs.json')], text=True)
        (proof / 'expected.txt').write_text(expected)
        assert result.stdout == expected
        manifest['validated'] = True
    assert source_hashes == {str(p): digest(p) for p in sources}
    (proof / 'manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
    print(f'{len(inputs) * 3} runtime input controls ' + ('prepared.' if args.prepare_only else 'passed; frozen sources unchanged.'))


if __name__ == '__main__':
    main()

